"""Сорок текстов164–205 кроме174/199; исходные области texts13_0..9.png прочитаны полностью."""
import json
from pathlib import Path
TEXTS = {164: 'Урон, который ты должен получить, уменьшен до 1.', 165: 'Когда игрок выбрасывает 5, получи 3¢.', 166: 'Когда ты умираешь, перед оплатой штрафа, получи 8¢.', 167: 'Поворот: выбери игрока. Этот игрок отдаёт тебе карту добычи. Гаппи.', 168: 'Поворот: выбери игрока. До конца хода, если он должен взять любое количество карт добычи, вместо этого он берёт их удвоенное количество.', 169: 'Поворот: выбери не-вечный пассивный предмет. Это становится копией того предмета до конца хода.', 170: 'Поворот: каждый игрок голосует за предмет в игре. Уничтожь предмет с большинством голосов. Если ничья, ничего не происходит.', 171: 'Платно: уничтожь 2 предмета под своим контролем: укради не-вечный предмет у игрока.', 172: 'Поворот: возьми 1 добычу. Затем положи карту добычи из своей руки на верх колоды добычи.', 173: 'Ты можешь посмотреть верхнюю карту колоды сокровищ в любой момент в свой ход. Ты можешь покупать дополнительный раз в свой ход.', 175: 'Поворот: брось кубик. 1–2: возьми 1 добычу. 3–4: получи 4¢.', 176: 'Когда игрок выбрасывает 2, ты можешь перезарядить предмет.', 177: 'Когда ты получаешь урон, положи жетоны на это, равные количеству полученного урона. Затем, если это имеет 6+ жетонов, сбрось 6 жетонов с этого и получи +1 сокровище.', 178: 'Платно: заплати 5¢: нанеси 1 урона монстру или игроку.', 179: 'В начале своего хода выбери случайного игрока. Этот игрок уничтожает не-вечный предмет под своим контролем.', 180: 'Когда ты получаешь урон, положи жетон на это. Платно: сбрось жетон с этого: предотврати следующую 1 урона, которую ты должен получить в этом ходу.', 181: 'Поворот: уничтожь это. Если ты сделал это, выбери одно: убей игрока или монстра; уничтожь предмет или душу.', 182: 'В конце своего хода посмотри 4 верхние карты колоды монстров. Положи их обратно в любом порядке.', 183: 'Поворот: положи верхнюю карту каждой колоды в сброс.', 184: 'Когда монстр умирает, получи 3¢.', 185: 'Поворот: брось кубик. 1–2: получи 1¢. 3–4: возьми 1 добычу. 5–6: получи +1 здоровья до конца хода.', 186: 'В конце своего хода ты можешь сбросить любое количество карт добычи, затем возьми добычу, равную количеству сброшенных таким образом карт.', 187: 'В конце своего хода посмотри 4 верхние карты колоды добычи. Положи их обратно в любом порядке.', 188: 'Поворот: в следующий раз, когда игрок должен взять добычу, вместо этого он берёт добычу сверху колоды сброса добычи.', 189: 'Поворот: уничтожь это. Если ты сделал это, ты можешь разыграть любое количество дополнительных карт добычи до конца хода.', 190: 'Когда ты умрёшь, перед оплатой штрафа, возьми 3 добычи.', 191: 'Поворот: заплати 1 здоровья. Если ты сделал это, выбери игрока. Предотврати до 2 следующего урона, которые он должен получить за раз в этом ходу. Гаппи.', 192: 'Поворот: нанеси 1 урона игроку.', 193: 'Поворот: положи карту монстра не-события из сброса на верх колоды монстров.', 194: 'Монстры имеют +1 защиты в твой ход. Когда ты умрёшь, перед оплатой штрафа, отдай это другому игроку.', 195: 'Поворот: выбери монстра или игрока. Следующий урон, который он должен получить за раз в этом ходу, уменьшен до 1.', 196: 'Возьми +1 добычу в свой шаг взятия добычи.', 197: 'Когда игрок выбрасывает 6, ты можешь нанести ему 1 урона.', 198: 'Когда игрок выбрасывает 4, ты можешь взять 1 добычу, затем сбрось карту добычи.', 200: 'Возьми +1 добычу в свой шаг взятия добычи.', 201: 'Когда игрок выбрасывает 3, ты можешь посмотреть его руку и украсть у него карту добычи.', 202: 'Этот предмет начинает с 9 жетонами на нём. Если ты должен получить урон, пока это имеет жетоны, сбрось столько же жетонов и предотврати столько же урона. Гаппи.', 203: 'Поворот: получи 1¢. Когда игрок выбрасывает 1, ты можешь перезарядить это.', 204: 'Поворот: отними до 2 от броска.', 205: 'Поворот: нанеси 1 урона монстру.'}
root = Path(__file__).resolve().parents[1]
p = root / "games/four_souls/art/card_texts.json"
data = json.loads(p.read_text(encoding="utf-8"))
cards = json.loads((root / "games/four_souls/art/manifest.json").read_text(encoding="utf-8"))["cards"]
for cid,text in TEXTS.items():
    data[str(cid)] = dict(name_ru=cards[cid]["name"].split("/")[0],type="treasure",text=text,stats={},reward="",verified_image=True,verified="2026-11-05",note="Прочитано в исходном масштабе texts13_0..9.png.")
p.write_text(json.dumps(data,ensure_ascii=False,indent=1)+"\n",encoding="utf-8")
